// Recorremos los datos
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  // Vamos a buscar el archivo binario al disco duro de n8n
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');

  // Lo transformamos a texto Base64
  items[i].json.fotoBase64 = buffer.toString('base64');
}

return items;

const items = $input.all();
const result = [];
for (const item of items) {
  const originalUrl = item.json.ImageURL;
  const transformedUrl = originalUrl.replace('/upload/', '/upload/c_pad,ar_1:1,w_1080,b_white/');
  const choice = item.json._choice || 'op1';
  let captionIG;
  if (choice === 'final' && item.json.Copy_Final) captionIG = item.json.Copy_Final;
  else if (choice === 'op2') captionIG = item.json.Copy_Op2;
  else if (choice === 'op3') captionIG = item.json.Copy_Op3;
  else captionIG = item.json.Copy_Op1;
  result.push({ json: { ...item.json, ImageURL_IG: transformedUrl, Caption_IG: captionIG } });
}
return result;

// HU9 — Compliance Sentinel: bloqueo de precios (HU7) + firma legal desde Config (BD central)
const items = $('Resolucion - IG').all();
const result = [];

// Firma/contacto desde la pestaña Config (BD central). Fallback a la línea legal histórica.
const FIRMA_FALLBACK = "-- Consultora de Belleza Independiente Mary Kay --";
// Config = pestaña con columnas (firma | contacto) y una fila de datos. Headers case-insensitive.
let cfg = {};
try {
  const row = (($('Leer Config').first() || {}).json) || {};
  for (const h of Object.keys(row)) cfg[h.trim().toLowerCase()] = String(row[h] ?? '').trim();
} catch (e) { /* Config ausente -> fallback */ }

const firmaLinea = cfg.firma || FIRMA_FALLBACK;
const contacto   = cfg.contacto || '';

// Patrones prohibidos por Mary Kay (HU7 - detección de precios en texto)
const patronesPrecios = [
  /\$\s?\d+/g,                    // $1500, $ 1500
  /\d+[\.,]\d{3}/g,               // 1.500, 1,500
  /\d+%\s?(off|desc)/gi,          // 50% off, 50% desc
  /\b(oferta|promocion|promo|descuento|rebaja|barato|economico|gratis)\b/gi
];

for (const item of items) {
  let caption = item.json.Caption_IG || '';
  let precioDetectado = false;
  let patronEncontrado = '';

  for (const patron of patronesPrecios) {
    const match = caption.match(patron);
    if (match) { precioDetectado = true; patronEncontrado = match[0]; break; }
  }

  if (precioDetectado) {
    result.push({ json: { ...item.json, compliance_ok: false,
      compliance_error: `⚠️ Postly detectó contenido prohibido: "${patronEncontrado}". Por las normas de Mary Kay no podés publicar precios ni promociones en el feed. Editá el texto e intentá de nuevo.` } });
    continue;
  }

  // Normalizar: la IA a veces escribe la firma inline (pegada a los #).
  // Quitamos firma/contacto donde estén y los reinsertamos limpios, cada uno en su renglón.
  caption = caption.trim();
  caption = caption.split(firmaLinea).join('').trim();
  if (contacto) caption = caption.split(contacto).join('').trim();
  caption = caption + '\n' + firmaLinea;
  if (contacto) caption = caption + '\n' + contacto;

  result.push({ json: { ...item.json, Caption_IG: caption, compliance_ok: true, compliance_error: null } });
}

return result;

const items = $input.all();
const chatId = $('Telegram Trigger').first().json.message.chat.id;
const rows = items.map(i => i.json).filter(j => j && (j.UserID || j.ImageURL || j.Status || j.Copy_Final || j.Copy_Op1));
if (rows.length === 0) {
  return [{ json: { chatId, texto: '📭 Todavía no tenés publicaciones en tu agenda.\n\nTocá 🚀 Nueva Publicación para crear tu primer post.', sinDatos: true, hasImage: false, estaPublicado: false, rowNumber: '' } }];
}
const ultimas = rows.slice(-5).reverse();
const result = [];
for (const r of ultimas) {
  const st = (r.Status || '').toString().toLowerCase();
  const estaPublicado = st === 'publicado';
  let estado;
  if (estaPublicado) estado = '🟢 Publicado';
  else if (st === 'fallido') estado = '🟡 Fallido';
  else estado = '🔴 Pendiente';
  const fecha = r.Timestamp ? new Date(r.Timestamp).toLocaleDateString('es-AR', { day: '2-digit', month: '2-digit', year: 'numeric' }) : 'Sin fecha';
  const copy = (r.Copy_Final || r.Copy_Op1 || '').toString();
  const copyResumen = copy.length > 120 ? copy.substring(0, 120) + '…' : (copy || '(sin texto)');
  const texto = estado + ' — ' + fecha + '\n\n📝 ' + copyResumen;
  const imageURL = r.ImageURL || null;
  result.push({ json: { chatId, texto, imageURL, hasImage: !!imageURL, rowNumber: r.row_number || '', estaPublicado, sinDatos: false } });
}
return result;

