const crypto = require('crypto');
const KEY = Buffer.from($env.POSTLY_ENC_KEY, 'hex');
function decrypt(val) {
  if (!val || typeof val !== 'string' || !val.startsWith('enc:')) return val; // texto plano (compat)
  const raw = Buffer.from(val.slice(4), 'base64');
  const iv  = raw.subarray(0, 12);
  const tag = raw.subarray(12, 28);
  const ct  = raw.subarray(28);
  const d = crypto.createDecipheriv('aes-256-gcm', KEY, iv);
  d.setAuthTag(tag);
  return Buffer.concat([d.update(ct), d.final()]).toString('utf8');
}
return $input.all().map(item => ({ json: { ...item.json, AccessToken: decrypt(item.json.AccessToken) } }));

